mapper.select:
SELECT t.questionId, q.title AS questionTitle, q.tags AS questionTags, t.id AS latestSubmissionId, t.language AS latestLanguage, t.code AS latestCode, t.status AS latestStatus, t.judgeInfo AS latestJudgeInfo, t.createTime AS latestSubmitTime, t.bestTime, t.bestMemory FROM ( SELECT questionId, id, language, code, status, judgeInfo, createTime, ROW_NUMBER() OVER (PARTITION BY questionId ORDER BY createTime DESC, id DESC) AS rn, MIN(CAST(JSON_EXTRACT(judgeInfo, '$.time') AS SIGNED)) OVER (PARTITION BY questionId) AS bestTime, MIN(CAST(JSON_EXTRACT(judgeInfo, '$.memory') AS SIGNED)) OVER (PARTITION BY questionId) AS bestMemory FROM question_submit WHERE isDelete = 0${judgeResultSql} AND language = #{language} AND userId = #{userId}
AND userId IN #{submitterId}
) t JOIN question q ON q.id = t.questionId AND q.isDelete = 0 WHERE t.rn = 1 ${orderSql}

SELECT COUNT(DISTINCT s.questionId)
FROM question_submit s
         JOIN question q ON q.id = s.questionId AND q.isDelete = 0
WHERE s.isDelete = 0${judgeResultSql}
AND s.language = #{language}
AND s.userId = #{userId}

    AND s.userId IN
    #{submitterId}

SELECT COUNT(CAST(JSON_EXTRACT(judgeInfo, '$.time') AS SIGNED))      AS timeTotal,
       SUM(CAST(JSON_EXTRACT(judgeInfo, '$.time') AS SIGNED) >= #{time})    AS timeBeaten,
       COUNT(CAST(JSON_EXTRACT(judgeInfo, '$.memory') AS SIGNED))    AS memoryTotal,
       SUM(CAST(JSON_EXTRACT(judgeInfo, '$.memory') AS SIGNED) >= #{memory}) AS memoryBeaten
FROM question_submit
WHERE ${acceptedSql}
  AND questionId = #{questionId}
  AND language = #{language}
  AND isDelete = 0
